+const MAX_PORT = 65535;
+
+function parsePortNumber(text: string, item: string): number {
+  if (!/^\d+$/.test(text)) {
+    throw new Error(`Invalid port "${item}"`);
+  }
+  const port = Number(text);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`Port out of range 1-${MAX_PORT} in "${item}"`);
+  }
+  return port;
+}
+
+function parseItem(rawItem: string): PortRange {
+  const item = rawItem.trim();
+  if (item === "") {
+    throw new Error("Empty item in port list");
+  }
+  const parts = item.split("-");
+  if (parts.length === 1) {
+    const port = parsePortNumber(item, item);
+    return [port, port];
+  }
+  if (parts.length !== 2) {
+    throw new Error(`Invalid port range "${item}"`);
+  }
+  const from = parsePortNumber(parts[0].trim(), item);
+  const to = parsePortNumber(parts[1].trim(), item);
+  if (to < from) {
+    throw new Error(`Port range end is below its start in "${item}"`);
+  }
+  return [from, to];
+}

